private async describeKeys(client: Redis, keys: string[]): Promise<RedisKeyItem[]> {
  if (!keys.length) return []
  const pipeline = client.pipeline()
  for (const key of keys) {
    pipeline.type(key)
    pipeline.ttl(key)
  }
  const replies = await pipeline.exec()

